arguments.file_text:
namespace sv_91e81f5925c8473dac6af13eb23117c1.Models;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

@page "/chat"
@using sv_91e81f5925c8473dac6af13eb23117c1.Models
@inject IChatService ChatService
@inject IJSRuntime JS
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    @* ── Left Sidebar: Channel List ── *@
    <aside class="channel-sidebar">
        <div class="sidebar-header">
            <h3>Channels</h3>
        </div>
        <ul class="channel-list">
            @foreach (var channel in channels)
            {
                <li class="channel-item @(channel.Id == activeChannelId ? "active" : "")"
                    @onclick="() => SelectChannelAsync(channel)">
                    <div class="channel-name"># @channel.Name</div>
                    <div class="channel-description">@TruncateDescription(channel.Description)</div>
                    @if (channel.UnreadCount > 0)
                    {
                        <span class="unread-badge">@channel.UnreadCount</span>
                    }
                </li>
            }
        </ul>
    </aside>

    @* ── Main Message Area ── *@
    <section class="message-area @(threadOpen ? "with-thread" : "full-width")">
        @if (activeChannel is not null)
        {
            <div class="message-header">
                <h2># @activeChannel.Name</h2>
                <p>@activeChannel.Description</p>
            </div>

            <div class="message-list" @ref="messageListRef" @onscroll="HandleScrollAsync">
                @if (isLoadingMore)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @foreach (var msg in messages)
                {
                    <div class="message-bubble" @onmouseenter="() => hoveredMessageId = msg.Id"
                         @onmouseleave="() => hoveredMessageId = null">
                        <div class="message-meta">
                            <strong class="message-author">@msg.Author</strong>
                            <time class="message-time">@FormatRelativeTime(msg.SentAt)</time>
                        </div>
                        <div class="message-content">@msg.Content</div>

                        @* Reactions *@
                        @if (msg.Reactions.Count > 0)
                        {
                            <div class="reaction-row">
                                @foreach (var reaction in msg.Reactions)
                                {
                                    <button class="reaction-badge" title="@string.Join(", ", reaction.Users)"
                                            @onclick="() => AddReactionAsync(msg.Id, reaction.Emoji)">
                                        @reaction.Emoji @reaction.Users.Count
                                    </button>
                                }
                            </div>
                        }

                        @* Thread replies link *@
                        @if (GetThreadSummary(msg.Id) is { } summary)
                        {
                            <button class="thread-link" @onclick="() => OpenThreadAsync(msg.Id)">
                                💬 @summary.ReplyCount @(summary.ReplyCount == 1 ? "reply" : "replies")
                                — last @FormatRelativeTime(summary.LastReplyAt)
                            </button>
                        }

                        @* Hover action buttons *@
                        @if (hoveredMessageId == msg.Id)
                        {
                            <div class="message-actions">
                                <button class="action-btn" title="Reply in thread"
                                        @onclick="() => OpenThreadAsync(msg.Id)">💬 Reply</button>
                                <div class="emoji-picker-wrapper">
                                    <button class="action-btn" title="Add reaction"
                                            @onclick="() => ToggleEmojiPicker(msg.Id)">😀 React</button>
                                    @if (emojiPickerMessageId == msg.Id)
                                    {
                                        <div class="emoji-picker">
                                            @foreach (var emoji in commonEmojis)
                                            {
                                                <button class="emoji-option"
                                                        @onclick="() => AddReactionAsync(msg.Id, emoji)">@emoji</button>
                                            }
                                        </div>
                                    }
                                </div>
                            </div>
                        }
                    </div>
                }
            </div>

            <div class="message-input-area">
                <textarea @bind="newMessageText" @bind:event="oninput"
                          placeholder="Message #@activeChannel.Name"
                          @onkeydown="HandleMessageKeyDown" rows="2"></textarea>
                <button class="send-btn" @onclick="SendMessageAsync" disabled="@string.IsNullOrWhiteSpace(newMessageText)">
                    Send
                </button>
            </div>
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </section>

    @* ── Right Panel: Thread View ── *@
    @if (threadOpen && threadRootMessage is not null)
    {
        <aside class="thread-panel">
            <div class="thread-header">
                <h3>Thread</h3>
                <button class="close-thread-btn" @onclick="CloseThread">✕</button>
            </div>

            <div class="thread-root-quote">
                <strong>@threadRootMessage.Author</strong>
                <time>@FormatRelativeTime(threadRootMessage.SentAt)</time>
                <p>@threadRootMessage.Content</p>
            </div>

            <div class="thread-replies">
                @foreach (var reply in threadReplies)
                {
                    <div class="message-bubble thread-reply">
                        <div class="message-meta">
                            <strong class="message-author">@reply.Author</strong>
                            <time class="message-time">@FormatRelativeTime(reply.SentAt)</time>
                        </div>
                        <div class="message-content">@reply.Content</div>
                    </div>
                }
            </div>

            <div class="message-input-area">
                <textarea @bind="threadReplyText" @bind:event="oninput"
                          placeholder="Reply…"
                          @onkeydown="HandleThreadKeyDown" rows="2"></textarea>
                <button class="send-btn" @onclick="SendThreadReplyAsync"
                        disabled="@string.IsNullOrWhiteSpace(threadReplyText)">
                    Reply
                </button>
            </div>
        </aside>
    }
</div>

@code {
    // ── State ──
    private List<Channel> channels = new();
    private List<Message> messages = new();
    private List<Message> threadReplies = new();
    private Dictionary<int, ThreadSummary> threadSummaries = new();

    private int activeChannelId;
    private Channel? activeChannel;
    private Message? threadRootMessage;
    private bool threadOpen;

    private string newMessageText = "";
    private string threadReplyText = "";

    private int? hoveredMessageId;
    private int? emojiPickerMessageId;

    private bool isLoadingMore;
    private bool hasMoreMessages = true;
    private const int PageSize = 30;

    private ElementReference messageListRef;

    private static readonly string[] commonEmojis = { "👍", "❤️", "😂", "🎉", "🚀", "👀" };

    // ── Lifecycle ──
    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannelAsync(channels[0]);
        }
    }

    // ── Channel Selection ──
    private async Task SelectChannelAsync(Channel channel)
    {
        activeChannelId = channel.Id;
        activeChannel = channel;
        messages.Clear();
        threadSummaries.Clear();
        hasMoreMessages = true;
        emojiPickerMessageId = null;

        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        hasMoreMessages = messages.Count >= PageSize;
        await BuildThreadSummaries();
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Refresh channel list to clear unread badge
        channels = await ChatService.GetChannelsAsync();
    }

    // ── Sending Messages ──
    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(newMessageText) || activeChannel is null) return;

        var sent = await ChatService.SendMessageAsync(activeChannel.Id, newMessageText.Trim(), null);
        messages.Add(sent);
        newMessageText = "";
        await ScrollToBottom();
    }

    private async Task HandleMessageKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessageAsync();
        }
    }

    // ── Infinite Scroll (load older messages) ──
    private async Task HandleScrollAsync()
    {
        if (isLoadingMore || !hasMoreMessages || activeChannel is null) return;

        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop > 50) return;

        isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(activeChannel.Id, messages.Count, PageSize);
        if (older.Count < PageSize) hasMoreMessages = false;

        messages.InsertRange(0, older);
        await BuildThreadSummaries();
        isLoadingMore = false;
    }

    // ── Reactions ──
    private void ToggleEmojiPicker(int messageId)
    {
        emojiPickerMessageId = emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task AddReactionAsync(int messageId, string emoji)
    {
        emojiPickerMessageId = null;
        await ChatService.AddReactionAsync(messageId, emoji);

        // Refresh messages to show updated reactions
        if (activeChannel is not null)
        {
            messages = await ChatService.GetMessagesAsync(activeChannel.Id, 0, messages.Count);
        }
    }

    // ── Thread Panel ──
    private async Task OpenThreadAsync(int rootMessageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (threadRootMessage is null) return;

        threadReplies = await ChatService.GetThreadAsync(rootMessageId);
        threadReplyText = "";
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies.Clear();
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(threadReplyText) || threadRootMessage is null || activeChannel is null) return;

        var reply = await ChatService.SendMessageAsync(activeChannel.Id, threadReplyText.Trim(), threadRootMessage.Id);
        threadReplies.Add(reply);
        threadReplyText = "";

        await BuildThreadSummaries();
    }

    private async Task HandleThreadKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendThreadReplyAsync();
        }
    }

    // ── Thread Summaries ──
    private async Task BuildThreadSummaries()
    {
        threadSummaries.Clear();
        // Identify root messages that have replies (ReplyToId is null = root candidate)
        var rootIds = messages
            .Where(m => m.ReplyToId is null)
            .Select(m => m.Id)
            .ToHashSet();

        // Count replies visible in current message set
        foreach (var msg in messages.Where(m => m.ReplyToId is not null && rootIds.Contains(m.ReplyToId.Value)))
        {
            var rootId = msg.ReplyToId!.Value;
            if (!threadSummaries.ContainsKey(rootId))
            {
                threadSummaries[rootId] = new ThreadSummary(rootId, 0, msg.SentAt);
            }
            var existing = threadSummaries[rootId];
            threadSummaries[rootId] = existing with
            {
                ReplyCount = existing.ReplyCount + 1,
                LastReplyAt = msg.SentAt > existing.LastReplyAt ? msg.SentAt : existing.LastReplyAt
            };
        }

        // Also supplement with data from the service for threads whose replies may not be loaded
        foreach (var rootId in rootIds)
        {
            if (!threadSummaries.ContainsKey(rootId))
            {
                try
                {
                    var threadMsgs = await ChatService.GetThreadAsync(rootId);
                    if (threadMsgs.Count > 0)
                    {
                        threadSummaries[rootId] = new ThreadSummary(
                            rootId,
                            threadMsgs.Count,
                            threadMsgs.Max(t => t.SentAt));
                    }
                }
                catch
                {
                    // Thread may not exist; skip
                }
            }
        }
    }

    private ThreadSummary? GetThreadSummary(int messageId) =>
        threadSummaries.GetValueOrDefault(messageId);

    // ── Helpers ──
    private static string FormatRelativeTime(DateTime sentAt)
    {
        var span = DateTime.UtcNow - sentAt;
        if (span.TotalSeconds < 60) return "just now";
        if (span.TotalMinutes < 60) return $"{(int)span.TotalMinutes} min ago";
        if (span.TotalHours < 24) return $"{(int)span.TotalHours}h ago";
        if (span.TotalDays < 7) return $"{(int)span.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }

    private static string TruncateDescription(string description) =>
        description.Length > 50 ? description[..47] + "…" : description;

    private async Task ScrollToBottom()
    {
        await Task.Delay(50); // Allow render
        await JS.InvokeVoidAsync("eval",
            "var el = document.querySelector('.message-list'); if(el) el.scrollTop = el.scrollHeight;");
    }
}

/* ── Layout ── */
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
